-- ReadyScore V19.7 — Work Attitude & Learning Preference Question Bank V2
-- Safe rollout: append immutable v2 QuestionVersion rows; preserve v1 for historical attempts.
-- No destructive question mutation. Active configuration/package is versioned forward using existing governance.

BEGIN;

-- 1) Create V2 assessment-facing versions for the existing logical Question identities.

-- 2) Create immutable V2 Assessment Configuration + runtime package versions.
UPDATE "AssessmentConfigurationVersion" SET "status"='ARCHIVED' WHERE "id" IN ('work-attitude-v1-version','learning-preference-v1-version') AND "status"='ACTIVE';
UPDATE "AssessmentConfigurationVersion" SET "questionPackageVersionId"='work-attitude-runtime-v2' WHERE "id"='work-attitude-v2-version';
UPDATE "AssessmentConfigurationVersion" SET "questionPackageVersionId"='learning-preference-runtime-v2' WHERE "id"='learning-preference-v2-version';

COMMIT;
